@Pipe({ name: 'initials' })
export class InitialsPipe implements PipeTransform {
  transform(name: string): string {
    return name.split(' ').map(p => p[0]).join('').toUpperCase();
  }
}

@Directive({
  selector: '[appHighlight]',
  host: { '[class.highlight]': 'active()', '(mouseenter)': 'active.set(true)', '(mouseleave)': 'active.set(false)' },
})
export class Highlight { active = signal(false); }

:host { display: block; --btn-bg: var(--color-primary); }
:host(.danger) { --btn-bg: var(--color-danger); }
button { background: var(--btn-bg); }

export const routes: Routes = [
  { path: 'admin', canMatch: [adminGuard], loadChildren: () => import('./admin/admin.routes') },
  { path: 'orders/:id', loadComponent: () => import('./orders/order-detail') },
];
export const adminGuard: CanMatchFn = () =>
  inject(Auth).isAdmin() || inject(Router).createUrlTree(['/login']);

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(Auth).token();
  return next(token ? req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }) : req);
};

